<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientAllowedRedirectsAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedRedirectsAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAllowedRedirectsAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAllowedRedirects returns null on a freshly created holder.
     */
    public function testAllowedRedirectsNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAllowedRedirectsAssigned());
        $this->assertNull($holder->getAllowedRedirects());
    }
}
class ImplWithTrustedClientAllowedRedirectsAttributeHolderUnitTest
{
    use TrustedClientAllowedRedirectsAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAllowedRedirectsRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAllowedRedirects();
    }
}
